PDI_PLUGIN(posix)

Read data tree: voidread_data_tree(PC_tree_tspec_tree){
PC_tree_tdata_tree=PC_get(spec_tree,".data");
if(!PC_status(data_tree)){
intdata_tree_size=PDI::len(data_tree);
for(inti=0;i<data_tree_size;i++){
PC_tree_tkey=PC_get(data_tree,"{%d}",i);
PC_tree_tvalue=PC_get(data_tree,"<%d>",i);
m_data_to_path_map.emplace_back(PDI::to_string(key),PDI::to_string(value));
}
}
}

Create a function that writes data to temporary file and check if file was created, size is correct and then replace old file: voidwrite_data(conststd::string&data_name,PDI::Ref_rref_r){
if(!ref_r){
return;
}
std::stringtmp_path=m_data_to_path_map[data_name]+".tmp";
std::ofstreamfile{tmp_path,std::ios::binary};
if(ref_r.type().buffersize()==ref_r.type().datasize()){
//densedata
file.write((constchar*)ref_r.get(),ref_r.type().buffersize());
}else{
//sparsedata
std::unique_ptr<char>data_copy{newchar[ref_r.type().dataSize()]};
ref_r.type().data_to_dense_copy(data_copy.get(),ref_r.get());
file.write(data_copy.get(),ref_r.type().datasize());
}
file.close();

//replaceoldfile
structstatstatus;
if(!stat(tmp_path.c_str(),&status)&&status.st_size==ref_r.type().datasize()){
if(!stat(m_data_to_path_map[data_name].c_str())&&std::remove(m_data_to_path_map[data_name].c_str())){
throwPDI::Error{PDI_ERR_SYSTEM,"Cannotremoveoldfile{}",m_data_to_path_map[data_name]};
}
if(std::rename(tmp_path.c_str(),m_data_to_path_map[data_name].c_str())){
throwPDI::Error{PDI_ERR_SYSTEM,"Cannotrenametemporaryfile{}",tmp_path};
}
}else{
throwPDI::Error{PDI_ERR_SYSTEM,"Datawritenotcomplete"};
}
}

Create a function that reads data from file: voidread_data(conststd::string&data_name,PDI::Ref_wref_w){
if(!ref_w){
return;
}
std::ifstreamfile{m_data_to_path_map[data_name],std::ios::binary};
if(ref_w.type().buffersize()==ref_w.type().datasize()){
//densedata
file.read((char*)ref_w.get(),ref_w.type().buffersize());
}else{
//sparsedata
std::unique_ptr<char>data_copy{newchar[ref_w.type().dataSize()]};
file.read(data_copy.get(),ref_w.type().datasize());
ref_w.type().data_from_dense_copy(ref_w.get(),data_copy.get());
}
}

Handle can_recover_all data: voidcan_recover(conststd::string&data_name,PDI::Ref_wref_w){
if(!ref_w){
throwPDI::Error{PDI_ERR_RIGHT,"Cannotwriteto`can_recover_all'data"};
}
for(constauto&data_path_pair:m_data_to_path_map){
structstatstatus;
if(stat(data_path_pair.second.c_str(),&status)){
*static_cast<int*>(ref_w.get())=0;
return;
}
}
*static_cast<int*>(ref_w.get())=1;
}

Add created functions to callbacks: classposix_plugin:publicPDI::Plugin
{
std::stringm_can_recover_data;
std::unordered_map<std::string,std::string>m_data_to_path_map;

public:
posix_plugin(PDI::Context&ctx,PC_tree_tspec_tree):
Plugin{ctx}
{
read_recover_tree(spec_tree);
read_data_tree(spec_tree);
for(constauto&data_path_pair:m_data_to_path_map){
ctx.callbacks().add_data_callback([this](conststd::string&data_name,PDI::Refref){
this->write_data(data_name,ref);
},data_path_pair.first);
ctx.callbacks().add_data_callback([this](conststd::string&data_name,PDI::Refref){
this->read_data(data_name,ref);
},data_path_pair.first);
}
if(!m_can_recover_data.empty()){
ctx.callbacks().add_data_callback([this](conststd::string&data_name,PDI::Refref){
this->can_recover(data_name,ref);
},m_can_recover_all_data);
}
}
}
